/** Typed generated bootstrap functions used by the Kotlin adapter. */
sealed interface GeneratedTdFunction {
    data class GetChats(val offsetChatId: Long, val limit: Int) : GeneratedTdFunction
    data class GetChatHistory(val chatId: Long, val fromMessageId: Long, val limit: Int) : GeneratedTdFunction
    data class SendMessage(
        val chatId: Long,
        val text: String,
        val replyToMessageId: Long?,
        val disableNotification: Boolean,
    ) : GeneratedTdFunction
}
